//! Benchmarks for SSZ encode/decode/hash of duty payloads.
//!
//! Benchmark ids follow the cross-language pair naming used by
//! `perf/pairs.json`; the Go counterparts live in `perf/go-bench/`. Fixtures
//! are shared binary files generated by the Go side
//! (`WRITE_FIXTURES=1 go test -run TestGenFixtures .` in `perf/go-bench/`);
//! each bench asserts a re-encode round-trip before timing so a workload
//! mismatch fails loudly instead of comparing different work.
#![allow(missing_docs)]

use std::time::Duration;

use criterion::{Criterion, criterion_group, criterion_main};
use pluto_core::ssz_codec::{
    decode_phase0_attestation, decode_versioned_signed_proposal, encode_phase0_attestation,
    encode_versioned_signed_proposal,
};
use std::hint::black_box;
use tree_hash::TreeHash;

const ATTESTATION_SSZ: &[u8] = include_bytes!("../../../perf/fixtures/phase0_attestation.ssz");
const PROPOSAL_SSZ: &[u8] = include_bytes!("../../../perf/fixtures/deneb_signed_proposal.ssz");

fn bench_attestation(c: &mut Criterion) {
    let att = decode_phase0_attestation(ATTESTATION_SSZ).expect("bench setup: decode attestation");
    let encoded = encode_phase0_attestation(&att).expect("bench setup: encode attestation");
    assert_eq!(
        encoded, ATTESTATION_SSZ,
        "attestation fixture round-trip mismatch"
    );

    c.bench_function("tier1/ssz/att_encode", |b| {
        b.iter(|| encode_phase0_attestation(black_box(&att)).expect("encode should succeed"))
    });

    c.bench_function("tier1/ssz/att_decode", |b| {
        b.iter(|| {
            decode_phase0_attestation(black_box(ATTESTATION_SSZ)).expect("decode should succeed")
        })
    });

    c.bench_function("tier1/ssz/att_hash_root", |b| {
        b.iter(|| black_box(&att).tree_hash_root())
    });
}

fn bench_proposal(c: &mut Criterion) {
    let proposal =
        decode_versioned_signed_proposal(PROPOSAL_SSZ).expect("bench setup: decode proposal");
    let encoded =
        encode_versioned_signed_proposal(&proposal).expect("bench setup: encode proposal");
    assert_eq!(
        encoded, PROPOSAL_SSZ,
        "proposal fixture round-trip mismatch"
    );

    c.bench_function("tier1/ssz/proposal_encode", |b| {
        b.iter(|| encode_versioned_signed_proposal(black_box(&proposal)).expect("encode"))
    });

    c.bench_function("tier1/ssz/proposal_decode", |b| {
        b.iter(|| decode_versioned_signed_proposal(black_box(PROPOSAL_SSZ)).expect("decode"))
    });
}

fn config() -> Criterion {
    Criterion::default()
        .sample_size(30)
        .measurement_time(Duration::from_secs(3))
}

criterion_group! {
    name = benches;
    config = config();
    targets = bench_attestation, bench_proposal,
}
criterion_main!(benches);
